<script setup lang="ts">
import { Link, router } from '@inertiajs/vue3';
import { computed, ref } from 'vue';

type OrderItem={id:number;product_id?:number|null;name:string;image:string;price:number;quantity:number;total?:number};
type OrderUser={id:number;name:string;email:string;phone?:string|null};
type Order={id:number;code:string;customer_name:string;customer_phone?:string|null;customer_email?:string|null;customer_address?:string|null;note?:string|null;payment:string;vat_invoice_requested:boolean;vat_company_name?:string|null;vat_tax_code?:string|null;vat_address?:string|null;vat_email?:string|null;vat_rate?:number|string;vat_amount?:number;paypal_order_id?:string|null;subtotal:number;shipping:number;total_shipping:number;total:number;status:string;created_at:string;items:OrderItem[];user?:OrderUser|null};
const props=defineProps<{orders:{data:Order[];current_page:number;last_page:number;total:number}}>();
const selectedOrder=ref<Order|null>(null),approveTarget=ref<Order|null>(null),editTarget=ref<Order|null>(null),deleteTarget=ref<Order|null>(null),deleteAllOpen=ref(false),approveBusy=ref(false),statusBusy=ref(false),editBusy=ref(false),deleteBusy=ref(false),deletePassword=ref(''),actionError=ref('');
const editForm=ref({customer_name:'',customer_phone:'',customer_email:'',customer_address:'',note:''});
const money=(n:number)=>new Intl.NumberFormat('vi-VN').format(Number(n||0))+' ₫';
const statusClass=(s:string)=>s==='Đã duyệt'?'is-approved':s==='Chờ xử lý'?'is-pending':s==='Đã giao'||s==='Hoàn tất'?'is-completed':s==='Hủy hàng'?'is-cancelled':'is-other';
const itemCount=computed(()=>selectedOrder.value?.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)??0);
const paymentLabel=(p:string)=>p==='paypal-sandbox'?'PayPal Sandbox':p==='paypal-demo'?'PayPal mô phỏng':'Thanh toán khi nhận hàng';
const nextStatus:Record<string,string|null>={'Chờ xử lý':'Đã duyệt','Đã duyệt':'Đang giao','Đang giao':'Đã giao','Đã giao':'Hoàn tất','Hoàn tất':null,'Hủy hàng':null,'Trả hàng':null};
const nextStatusLabel=(s:string)=>nextStatus[s]??'';
function openOrder(o:Order){selectedOrder.value=o}function closeOrder(){selectedOrder.value=null}
function requestApprove(o:Order){if(o.status!=='Chờ xử lý')return;actionError.value='';approveTarget.value=o}function closeApprove(){if(!approveBusy.value)approveTarget.value=null}
function confirmApprove(){const o=approveTarget.value;if(!o||approveBusy.value)return;approveBusy.value=true;router.patch(`/admin/orders/${o.id}/approve`,{}, {preserveScroll:true,onSuccess:()=>{approveTarget.value=null;selectedOrder.value=null},onError:()=>{actionError.value='Không thể duyệt đơn hàng. Vui lòng thử lại.'},onFinish:()=>approveBusy.value=false})}
function moveToNextStatus(o:Order){const status=nextStatus[o.status];if(!status||statusBusy.value)return;statusBusy.value=true;actionError.value='';router.patch(`/admin/orders/${o.id}/status`,{status},{preserveScroll:true,onSuccess:()=>{selectedOrder.value=null},onError:()=>{actionError.value='Không thể cập nhật trạng thái đơn hàng. Vui lòng thử lại.'},onFinish:()=>statusBusy.value=false})}
function requestEdit(o:Order){editTarget.value=o;editForm.value={customer_name:o.customer_name,customer_phone:o.customer_phone??'',customer_email:o.customer_email??'',customer_address:o.customer_address??'',note:o.note??''};actionError.value=''}function closeEdit(){if(!editBusy.value)editTarget.value=null}
function submitEdit(){const o=editTarget.value;if(!o||editBusy.value)return;editBusy.value=true;router.patch(`/admin/orders/${o.id}`,editForm.value,{preserveScroll:true,onSuccess:()=>{editTarget.value=null;selectedOrder.value=null},onError:()=>{actionError.value='Không thể cập nhật thông tin người nhận. Kiểm tra lại dữ liệu.'},onFinish:()=>editBusy.value=false})}
function requestDelete(o:Order){deletePassword.value='';deleteTarget.value=o;actionError.value=''}function closeDelete(){if(!deleteBusy.value){deleteTarget.value=null;deletePassword.value=''}}
function confirmDelete(){const o=deleteTarget.value;if(!o||deleteBusy.value||!deletePassword.value)return;deleteBusy.value=true;router.delete(`/admin/orders/${o.id}`,{data:{password:deletePassword.value},preserveScroll:true,onSuccess:()=>{deleteTarget.value=null;selectedOrder.value=null;deletePassword.value=''},onError:()=>{actionError.value='Mật khẩu admin không đúng hoặc không thể xóa đơn hàng.'},onFinish:()=>deleteBusy.value=false})}
function requestDeleteAll(){deletePassword.value='';deleteAllOpen.value=true;actionError.value=''}function closeDeleteAll(){if(!deleteBusy.value){deleteAllOpen.value=false;deletePassword.value=''}}
function confirmDeleteAll(){if(deleteBusy.value||!deletePassword.value)return;deleteBusy.value=true;router.delete('/admin/orders',{data:{password:deletePassword.value},preserveScroll:true,onSuccess:()=>{deleteAllOpen.value=false;deletePassword.value=''},onError:()=>{actionError.value='Mật khẩu admin không đúng hoặc không thể xóa toàn bộ đơn hàng.'},onFinish:()=>deleteBusy.value=false})}
</script>
<template><div class="admin-page">
<div class="admin-page-head"><div><div class="admin-kicker">ĐƠN HÀNG</div><h1>Duyệt đơn hàng</h1><p>Kiểm tra đầy đủ thông tin khách hàng, sản phẩm, thanh toán và hóa đơn trước khi duyệt.</p></div><div class="admin-head-actions"><div class="admin-chip"><i class="bi bi-inbox me-2"/>{{props.orders.total}} đơn</div><button type="button" class="delete-all-btn" :disabled="!props.orders.total" @click="requestDeleteAll"><i class="bi bi-trash3"/> Xóa tất cả</button></div></div>
<div v-if="actionError" class="orders-action-error"><i class="bi bi-exclamation-circle"/><span>{{actionError}}</span><button type="button" @click="actionError=''" aria-label="Đóng"><i class="bi bi-x"/></button></div>
<div class="orders-admin-panel"><div class="orders-admin-toolbar"><div><strong>Danh sách đơn hàng</strong><span>{{props.orders.total}} đơn trong hệ thống</span></div><div class="orders-admin-legend"><span><i class="dot pending"/> Chờ xử lý</span><span><i class="dot approved"/> Đã duyệt</span><span><i class="dot completed"/> Đã giao / Hoàn tất</span></div></div><div class="table-responsive"><table class="table orders-admin-table align-middle"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Liên hệ</th><th>Ngày đặt</th><th>Số SP</th><th>Tổng tiền</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody><tr v-for="o in props.orders.data" :key="o.id"><td><button type="button" class="order-code-btn" @click="openOrder(o)">{{o.code}}</button><small>ID #{{o.id}}</small></td><td><strong>{{o.customer_name}}</strong><small>{{o.user?.email||o.customer_email||'Chưa có Email'}}</small></td><td>{{o.customer_phone||o.user?.phone||'—'}}</td><td>{{new Date(o.created_at).toLocaleString('vi-VN')}}</td><td>{{o.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)}}</td><td class="money-cell">{{money(o.total)}}</td><td><span :class="['order-status-badge',statusClass(o.status)]"><i class="bi bi-circle-fill"/>{{o.status}}</span></td><td><div class="order-table-actions"><button type="button" class="detail-btn" @click="openOrder(o)"><i class="bi bi-eye"/> Chi tiết</button><button v-if="o.status==='Chờ xử lý'" type="button" class="approve-btn" @click="requestApprove(o)"><i class="bi bi-check2"/> Duyệt</button><button v-else-if="nextStatus[o.status]" type="button" class="approve-btn next-status-btn" :disabled="statusBusy" @click="moveToNextStatus(o)"><i :class="['bi',statusBusy?'bi-arrow-repeat spin':'bi-arrow-right-circle']"/> {{nextStatusLabel(o.status)}}</button><button type="button" class="edit-btn" @click="requestEdit(o)"><i class="bi bi-pencil-square"/> Sửa</button><button type="button" class="delete-btn" @click="requestDelete(o)"><i class="bi bi-trash3"/> Xóa</button></div></td></tr><tr v-if="!props.orders.data.length"><td colspan="8" class="text-center py-5 text-secondary">Chưa có đơn hàng.</td></tr></tbody></table></div></div>
<div v-if="props.orders.last_page>1" class="d-flex justify-content-center gap-1 mt-3"><Link v-for="p in props.orders.last_page" :key="p" :href="`/admin/orders?page=${p}`" class="btn btn-sm" :class="p===props.orders.current_page?'btn-primary':'btn-light'">{{p}}</Link></div>
<Teleport to="body"><div v-if="selectedOrder" class="order-detail-overlay" @click.self="closeOrder"><section class="order-detail-drawer" role="dialog" aria-modal="true"><header class="order-detail-head"><div><span class="drawer-kicker">CHI TIẾT ĐƠN HÀNG</span><h2>{{selectedOrder.code}}</h2><small>{{new Date(selectedOrder.created_at).toLocaleString('vi-VN')}}</small></div><div class="drawer-head-actions"><span :class="['order-status-badge',statusClass(selectedOrder.status)]"><i class="bi bi-circle-fill"/>{{selectedOrder.status}}</span><button type="button" class="drawer-close" @click="closeOrder"><i class="bi bi-x-lg"/></button></div></header><div class="order-detail-body"><section class="detail-section"><div class="detail-section-title"><i class="bi bi-person-vcard"/><div><strong>Thông tin khách hàng</strong><small>Thông tin tài khoản và lúc đặt hàng</small></div></div><div class="customer-grid"><div><span>Họ và tên</span><strong>{{selectedOrder.customer_name}}</strong></div><div><span>Email tài khoản</span><strong>{{selectedOrder.user?.email||'—'}}</strong></div><div><span>Số điện thoại</span><strong>{{selectedOrder.customer_phone||selectedOrder.user?.phone||'—'}}</strong></div><div><span>Email đặt hàng</span><strong>{{selectedOrder.customer_email||'—'}}</strong></div><div class="full"><span>Địa chỉ nhận hàng</span><strong>{{selectedOrder.customer_address||'—'}}</strong></div><div v-if="selectedOrder.note" class="full"><span>Ghi chú</span><strong>{{selectedOrder.note}}</strong></div></div></section><section class="detail-section"><div class="detail-section-title"><i class="bi bi-box-seam"/><div><strong>Sản phẩm</strong><small>{{itemCount}} sản phẩm trong đơn</small></div></div><div class="detail-products"><article v-for="item in selectedOrder.items" :key="`${selectedOrder.id}-${item.id}`" class="detail-product"><div class="detail-product-image"><img :src="item.image" :alt="item.name"/></div><div class="detail-product-copy"><strong>{{item.name}}</strong><small>Đơn giá {{money(item.price)}} · Số lượng {{item.quantity}}</small></div><b>{{money(item.total??item.price*item.quantity)}}</b></article></div></section><section class="detail-columns"><div class="detail-section compact"><div class="detail-section-title"><i class="bi bi-credit-card"/><div><strong>Thanh toán</strong><small>Phương thức và tổng tiền</small></div></div><div class="info-list"><div><span>Phương thức</span><strong>{{paymentLabel(selectedOrder.payment)}}</strong></div><div><span>Tạm tính</span><strong>{{money(selectedOrder.subtotal)}}</strong></div><div><span>Phí vận chuyển</span><strong>{{money(selectedOrder.total_shipping)}}</strong></div><div v-if="selectedOrder.paypal_order_id"><span>Mã PayPal</span><strong>{{selectedOrder.paypal_order_id}}</strong></div><div><span>Tổng thanh toán</span><strong class="grand-total">{{money(selectedOrder.total)}}</strong></div></div></div><div class="detail-section compact"><div class="detail-section-title"><i class="bi bi-receipt-cutoff"/><div><strong>Hóa đơn VAT</strong><small>Thông tin xuất hóa đơn</small></div></div><div v-if="selectedOrder.vat_invoice_requested" class="info-list"><div><span>Doanh nghiệp / đơn vị</span><strong>{{selectedOrder.vat_company_name||'—'}}</strong></div><div><span>Mã số thuế</span><strong>{{selectedOrder.vat_tax_code||'—'}}</strong></div><div><span>Email</span><strong>{{selectedOrder.vat_email||'—'}}</strong></div><div><span>Địa chỉ</span><strong>{{selectedOrder.vat_address||'—'}}</strong></div><div><span>Thuế GTGT</span><strong>{{Number(selectedOrder.vat_rate||0).toFixed(0)}}% · {{money(Number(selectedOrder.vat_amount||0))}}</strong></div></div><div v-else class="no-vat"><i class="bi bi-file-earmark-x"/> Đơn hàng không yêu cầu xuất hóa đơn VAT.</div></div></section></div><footer class="order-detail-foot"><button type="button" class="secondary-detail-btn" @click="closeOrder">Đóng</button><button v-if="nextStatus[selectedOrder.status]" type="button" class="approve-detail-btn" :disabled="statusBusy" @click="moveToNextStatus(selectedOrder)"><i :class="['bi',statusBusy?'bi-arrow-repeat spin':'bi-arrow-right-circle']"/> {{statusBusy?'Đang cập nhật...':nextStatusLabel(selectedOrder.status)}}</button><button type="button" class="detail-edit-btn" @click="requestEdit(selectedOrder)"><i class="bi bi-pencil-square"/> Sửa người nhận</button><button type="button" class="detail-delete-btn" @click="requestDelete(selectedOrder)"><i class="bi bi-trash3"/> Xóa đơn hàng</button><button v-if="selectedOrder.status==='Chờ xử lý'" type="button" class="approve-detail-btn" @click="requestApprove(selectedOrder)"><i class="bi bi-check2-circle"/> Duyệt đơn hàng</button></footer></section></div></Teleport>
<Teleport to="body"><div v-if="approveTarget" class="approve-overlay" @click.self="closeApprove"><section class="approve-dialog" role="dialog" aria-modal="true"><div class="approve-icon"><i class="bi bi-check2-circle"/></div><div class="approve-copy"><span>XÁC NHẬN XỬ LÝ</span><h2>Duyệt đơn hàng?</h2><p>Bạn đang xác nhận đơn <strong>#{{approveTarget.code}}</strong> của <strong>{{approveTarget.customer_name}}</strong>.</p><div class="approve-summary"><div><span>Tổng thanh toán</span><strong>{{money(approveTarget.total)}}</strong></div><div><span>Sản phẩm</span><strong>{{approveTarget.items.reduce((sum,item)=>sum+Number(item.quantity||0),0)}} sản phẩm</strong></div></div><div class="approve-warning"><i class="bi bi-info-circle-fill"/><span>Sau khi duyệt, đơn hàng sẽ chuyển sang <strong>Đã duyệt</strong> và hệ thống sẽ xử lý tồn kho theo quy trình.</span></div></div><footer><button type="button" class="approve-cancel" :disabled="approveBusy" @click="closeApprove">Hủy</button><button type="button" class="approve-confirm" :disabled="approveBusy" @click="confirmApprove"><i :class="['bi',approveBusy?'bi-arrow-repeat spin':'bi-check-lg']"/>{{approveBusy?'Đang duyệt...':'Xác nhận duyệt'}}</button></footer></section></div></Teleport>
<Teleport to="body"><div v-if="editTarget" class="approve-overlay" @click.self="closeEdit"><section class="approve-dialog edit-dialog" role="dialog" aria-modal="true"><div class="approve-icon"><i class="bi bi-pencil-square"/></div><div class="approve-copy"><span>CẬP NHẬT ĐƠN HÀNG</span><h2>Sửa thông tin người nhận</h2><div class="edit-form"><label>Họ và tên<input v-model.trim="editForm.customer_name" type="text" maxlength="255"/></label><label>Số điện thoại<input v-model.trim="editForm.customer_phone" type="tel" maxlength="30"/></label><label>Email<input v-model.trim="editForm.customer_email" type="email" maxlength="255"/></label><label class="full-field">Địa chỉ nhận hàng<textarea v-model.trim="editForm.customer_address" maxlength="500" rows="3"></textarea></label><label class="full-field">Ghi chú<textarea v-model.trim="editForm.note" maxlength="5000" rows="3"></textarea></label></div></div><footer><button type="button" class="approve-cancel" :disabled="editBusy" @click="closeEdit">Hủy</button><button type="button" class="approve-confirm" :disabled="editBusy" @click="submitEdit"><i :class="['bi',editBusy?'bi-arrow-repeat spin':'bi-check-lg']"/>{{editBusy?'Đang lưu...':'Lưu thay đổi'}}</button></footer></section></div></Teleport>
<Teleport to="body"><div v-if="deleteTarget" class="approve-overlay" @click.self="closeDelete"><section class="approve-dialog danger-dialog" role="dialog" aria-modal="true"><div class="approve-icon danger-icon"><i class="bi bi-shield-lock"/></div><div class="approve-copy"><span>XÁC NHẬN XÓA</span><h2>Xóa đơn hàng?</h2><p>Đơn <strong>#{{deleteTarget.code}}</strong> sẽ bị xóa khỏi hệ thống. Thao tác này không thể hoàn tác.</p><label class="password-field"><span>Mật khẩu quản trị viên</span><input v-model="deletePassword" type="password" autocomplete="current-password" placeholder="Nhập mật khẩu admin" @keyup.enter="confirmDelete"/></label></div><footer><button type="button" class="approve-cancel" :disabled="deleteBusy" @click="closeDelete">Hủy</button><button type="button" class="danger-confirm" :disabled="deleteBusy||!deletePassword" @click="confirmDelete"><i :class="['bi',deleteBusy?'bi-arrow-repeat spin':'bi-trash3']"/>{{deleteBusy?'Đang xóa...':'Xóa đơn hàng'}}</button></footer></section></div></Teleport>
<Teleport to="body"><div v-if="deleteAllOpen" class="approve-overlay" @click.self="closeDeleteAll"><section class="approve-dialog danger-dialog" role="dialog" aria-modal="true"><div class="approve-icon danger-icon"><i class="bi bi-trash3-fill"/></div><div class="approve-copy"><span>XÓA TOÀN BỘ</span><h2>Xóa tất cả đơn hàng?</h2><p>Toàn bộ <strong>{{props.orders.total}} đơn hàng</strong> và các sản phẩm trong đơn sẽ bị xóa vĩnh viễn. Hãy kiểm tra kỹ trước khi tiếp tục.</p><label class="password-field"><span>Mật khẩu quản trị viên</span><input v-model="deletePassword" type="password" autocomplete="current-password" placeholder="Nhập mật khẩu admin" @keyup.enter="confirmDeleteAll"/></label></div><footer><button type="button" class="approve-cancel" :disabled="deleteBusy" @click="closeDeleteAll">Hủy</button><button type="button" class="danger-confirm" :disabled="deleteBusy||!deletePassword" @click="confirmDeleteAll"><i :class="['bi',deleteBusy?'bi-arrow-repeat spin':'bi-trash3-fill']"/>{{deleteBusy?'Đang xóa...':'Xóa tất cả'}}</button></footer></section></div></Teleport>
</div></template>
<style scoped>
